  `group_order` int(3) NOT NULL,
  `group_token` varchar(255) NOT NULL,
  `group_filename` varchar(1000) NOT NULL,
  `group_status` int(1) NOT NULL,
  `structure_id` int(3) NOT NULL,
  `facebook_id` varchar(255) NOT NULL,
  `additional_fields` longtext NOT NULL,
  `group_type` varchar(255) NOT NULL,
  `data_type` int(3) NOT NULL DEFAULT 14,
  `data_id` int(3) NOT NULL,
  `group_category` varchar(255) NOT NULL,
  `revision_timestamp` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `lat` varchar(255) NOT NULL,
  `lon` varchar(255) NOT NULL,
  `post_tags` longtext NOT NULL,
  `upload_image_slide` varchar(255) NOT NULL,
  `post_review` varchar(111) NOT NULL,
  `property_status` varchar(255) NOT NULL,
  `property_type` varchar(255) NOT NULL,
  `reference_url_idea` varchar(225) NOT NULL,
  `property_price` decimal(20,2) DEFAULT NULL,
  `annual_price` decimal(20,2) DEFAULT NULL,
  `property_beds` decimal(3,1) NOT NULL,
  `property_baths` decimal(3,1) NOT NULL,
  `property_sqr_foot` decimal(10,2) DEFAULT NULL,
  `sticky_post` tinyint(1) NOT NULL COMMENT 'field to control the sticky post order',
  `post_location` varchar(255) NOT NULL,
  `sticky_post_expiration_date` date NOT NULL COMMENT 'date to know when sticky_post have action',
  `country_sn` varchar(20) NOT NULL COMMENT 'field to control the post country',
  `state_sn` varchar(20) NOT NULL COMMENT 'field to control the post state',
  `revision_count` bigint(20) NOT NULL DEFAULT 0 COMMENT 'this would count how many time a post have been saved',
  `post_excerpt` longtext DEFAULT NULL,
  `price_unit` mediumtext NOT NULL,
  `product_type` mediumtext NOT NULL,
  `price_duration` mediumtext NOT NULL,
  `widget_name` varchar(255) NOT NULL,
  `delivery_time_title` mediumtext NOT NULL,
  `delivery_time_description` mediumtext NOT NULL,
  `warranty_time_title` mediumtext NOT NULL,
  `description_time_description` mediumtext NOT NULL,
  `demo_video` mediumtext NOT NULL,
  `short_title` varchar(255) NOT NULL,
  `short_title_for_results` varchar(255) NOT NULL,
  `implementation_type` varchar(255) NOT NULL,
  `tool_subscription_type` varchar(255) NOT NULL,
  `commitment_price` decimal(20,2) DEFAULT NULL,
  `starts_from_type` mediumtext NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

